// ── 1. Greetings ────────────────────────────────────────────────────────

const GREETINGS: FrenchLesson[] = [
  {id:"french_greetings_intro",level:"A1",category:"greetings",title_vi:"Chào hỏi cơ bản",title_en:"Basic greetings",
    sentences:[{en:"Bonjour, je m'appelle Marie.",vi:"Xin chào, tôi tên là Marie.",pronunciation_focus:["nasal on","nasal in","silent -e","elle → èl"]},{en:"Enchanté de faire votre connaissance.",vi:"Rất vui được làm quen với bạn.",pronunciation_focus:["nasal en","nasal an","é → ê","silent -re"]},{en:"Comment allez-vous aujourd'hui ?",vi:"Hôm nay bạn khỏe không?",pronunciation_focus:["nasal ent","ez → ê","u → uy","hui → u-i"]},{en:"Je vais bien, merci. Et vous ?",vi:"Tôi khỏe, cảm ơn. Còn bạn?",pronunciation_focus:["nasal en","silent -s","er → ê"]},{en:"Au revoir et bonne journée !",vi:"Tạm biệt và chúc một ngày tốt lành!",pronunciation_focus:["au → ô","oi → oa","ou → u","ée → ê"]}],
    cultural_notes_vi:"Người Pháp chào bằng 'bonjour' suốt cả ngày đến tầm 6 giờ tối mới chuyển sang 'bonsoir'. Dùng 'salut' với bạn bè thân, không dùng với người lớn tuổi hay lần đầu gặp. 'Enchanté' (nam) / 'Enchantée' (nữ) là câu lịch sự chuẩn khi gặp lần đầu.",
    tip_advice_vi:"Khi gặp người Pháp, luôn nói 'bonjour' TRƯỚC khi hỏi bất cứ điều gì — kể cả hỏi đường. Vào tiệm bánh mà không chào 'bonjour' là bị coi là bất lịch sự. Tập phát âm âm mũi (bonjour, enchanté, bien) — đó là điểm yếu nhất của người Việt học tiếng Pháp."},
];

