// ── 4. Basic Grammar ────────────────────────────────────────────────────

const BASIC_GRAMMAR: FrenchLesson[] = [
  {id:"french_grammar_gender",level:"A1",category:"basic_grammar",title_vi:"Giống đực và giống cái",title_en:"Masculine and feminine gender",
    sentences:[{en:"Le garçon est petit. La fille est petite.",vi:"Cậu bé thì nhỏ. Cô bé thì nhỏ.",pronunciation_focus:["le → lơ","la → la","nasal on","silent -t","e muet"]},{en:"Un bon café. Une bonne baguette.",vi:"Một ly cà phê ngon. Một ổ bánh mì ngon.",pronunciation_focus:["nasal un","nasal on","bon → bon nasal","bonne → bon"]},{en:"Le chat noir. La voiture rouge.",vi:"Con mèo đen. Chiếc xe hơi đỏ.",pronunciation_focus:["le / la distinction","oi → oa","ou → u","r uvulaire"]},{en:"Mon ami, mon amie — same sound!",vi:"Bạn trai tôi, bạn gái tôi — nghe giống nhau!",pronunciation_focus:["nasal on","mon → mon nasal","amie → a-mi","liaison mon‿ami"]},{en:"Les enfants sont gentils.",vi:"Lũ trẻ thì ngoan.",pronunciation_focus:["les → lê","nasal en","nasal on","gentils → jan-ti"]}],
    cultural_notes_vi:"Tiếng Pháp chia mọi danh từ thành giống đực (le/un) hoặc giống cái (la/une). Không có quy tắc tuyệt đối — phải học thuộc từng từ. Mẹo: từ kết thúc bằng -tion, -sion, -té thường là giống cái. Từ kết thúc bằng -age, -ment thường là giống đực.",
    tip_advice_vi:"Đừng sợ sai giống đực/cái — người Pháp vẫn hiểu bạn. Tập thói quen học mỗi danh từ KÈM mạo từ: không học 'pain' mà học 'LE pain'."},
];

